#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trisolv.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x[i] = - 999;
      b[i] =  i ;
      for (j = 0; j <= i; j++)
	L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trisolv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i;

  /* Optimized forward substitution:
   *
   * Original code:
   *   for (i = 0; i < _PB_N; i++) {
   *     x[i] = b[i];
   *     for (j = 0; j < i; j++)
   *       x[i] -= L[i][j] * x[j];
   *     x[i] = x[i] / L[i][i];
   *   }
   *
   * This performs a standard lower-triangular solve. The optimized
   * version below:
   *   - keeps exactly the same arithmetic order (no reassociation),
   *   - keeps the current row L[i][*] in a row pointer to avoid
   *     recomputing addresses,
   *   - uses a scalar accumulator 'sum' so that x[i] stays in a
   *     register throughout the inner loop instead of being repeatedly
   *     loaded and stored,
   *   - manually unrolls the inner loop by a factor of 4 to increase
   *     instruction-level parallelism while preserving the order of
   *     operations (j = 0,1,2,3,4,...).
   *
   * As a result, memory traffic and address computation overhead are
   * reduced, improving computational efficiency and cache behavior
   * without changing the numerical results.
   */

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      const DATA_TYPE *Li = L[i];  /* Pointer to current row of L.  */
      DATA_TYPE        sum = b[i]; /* Accumulator for x[i].         */
      int j = 0;

      /* Manually unrolled inner loop (factor 4).
       *
       * For each group, we perform:
       *   sum -= Li[j]   * x[j];
       *   sum -= Li[j+1] * x[j+1];
       *   sum -= Li[j+2] * x[j+2];
       *   sum -= Li[j+3] * x[j+3];
       *
       * which is exactly equivalent to four separate iterations of
       * the original loop with j, j+1, j+2, j+3, i.e. the arithmetic
       * order is preserved: the sequence of operations on 'sum' is
       * still for j = 0,1,2,3,...
       */
      for (; j + 3 < i; j += 4)
        {
          sum -= Li[j]     * x[j];
          sum -= Li[j + 1] * x[j + 1];
          sum -= Li[j + 2] * x[j + 2];
          sum -= Li[j + 3] * x[j + 3];
        }

      /* Handle the remaining elements (at most 3). */
      for (; j < i; ++j)
        {
          sum -= Li[j] * x[j];
        }

      /* Single division by the diagonal element. */
      DATA_TYPE diag = Li[i];
      x[i] = sum / diag;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trisolv (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
